custom_css:
/* 免费公开发布于类脑，仅限个人使用
 * 请勿二改/二传，倒卖贩子死全家 */

@import url('https://cdn.jsdelivr.net/gh/endlessrefrain/sillytavern-themes@main/蕾丝天使.css');

/* 毛玻璃: 修改酒馆自带的UI背景颜色(颜色、透明度)，以及模糊强度
 * 引号字体/斜体字颜色: 在酒馆自带设置里调整 */

:root {
  --聊天背景模糊: 1px;
  --思维链标题: "思考了一下";
  --思维链花体英文: "good morning";
  --size-1: 14px; /* 思维链美化字体大小 */
  --英文字体: "ZSFT-l";
  --输入框占位文字: "";

  /* 高度不够聊天窗会有滚动条bug，按需调整 */
  --输入框高度: 9px;
  --输入框高度-下: 4px;
  --正文首行缩进: 2em; /* 不要就留空 */
  --正文左右边距: 10px;

  /* 头像默认设置垂直居中显示，可修改第二位百分比(-50%至150%之间)上下移动显示区域: 数值越小越上移 */
  --Char头像显示区域: center 50%;
  --User头像显示区域: center 50%;
  --时间戳及姓名显示: 0; /* 1开0关 */
}

/* 为不同角色卡/User设置不同的头像显示区域，代码如下:
*/
#chat .mes[ch_name="琥珀糖"] .avatar img {
  object-position: center 30%;
}

#chat .mes[ch_name="糖珀琥"] .avatar img {
  object-position: center 120%;
}

#chat .mes[ch_name="角色卡名字B"] .avatar img {
  object-position: center 60%;
}
